"""Schedule playback markers from sent audio and provider word timestamps."""

import math
from typing import List

import structlog

from rasa.core.channels.voice_stream.tts.tts_engine import (
    TTSWordTimestamp,
    TTSWordTimestamps,
)
from rasa.shared.core.playback_marker import PlaybackPosition

structlogger = structlog.get_logger(__name__)

_ELAPSED_MARKER_INTERVAL_MS = 1000


class MarkerScheduler:
    """Schedule monotonic playback markers after audio has been sent.

    Word marks follow timestamp ends. When sent audio runs a full second past
    the last marker and no pending word starts before that mark, an elapsed
    marker is sent. After a dropped timestamp, the same markers fill the gap
    until a later word arrives. ``word_index`` is the word's position in the
    provider's word stream: every parsed timestamp, including zero-length
    words and ones dropped as late, consumes the next number.
    """

    def __init__(self) -> None:
        """Initialize an empty marker timeline."""
        self._pending_timestamps: List[TTSWordTimestamp] = []
        self._last_progress_ms = 0
        self._next_word_index = 0
        self._timestamps_dropped = False

    def after_audio_sent(
        self,
        window_start_ms: int,
        sent_ms: int,
        timestamp_batches: List[TTSWordTimestamps],
    ) -> List[PlaybackPosition]:
        """Return markers aligned with the latest sent-audio window.

        Args:
            window_start_ms: Sent-audio position before this send. When the
                send advances that position, timestamps that end at or behind
                it are dropped. A drain that stays at the same position keeps
                words ending within audio already sent.
            sent_ms: Sent-audio position after this send.
            timestamp_batches: Word timestamps drained without waiting.

        Returns:
            Intermediate marker payloads in emit order.
        """
        self._add_timestamps(timestamp_batches)
        markers = self._consume_word_markers(window_start_ms, sent_ms)
        markers.extend(self._elapsed_markers(sent_ms))
        return markers

    def _add_timestamps(self, timestamp_batches: List[TTSWordTimestamps]) -> None:
        invalid_count = 0
        for batch in timestamp_batches:
            for timestamp in batch.timestamps:
                if self._is_valid(timestamp):
                    self._pending_timestamps.append(timestamp)
                else:
                    invalid_count += 1
        self._pending_timestamps.sort(
            key=lambda timestamp: (timestamp.end_seconds, timestamp.start_seconds)
        )
        if invalid_count:
            structlogger.warning(
                "voice_channel.invalid_word_timestamps",
                invalid_count=invalid_count,
            )

    def _consume_word_markers(
        self, window_start_ms: int, sent_ms: int
    ) -> List[PlaybackPosition]:
        markers: List[PlaybackPosition] = []
        while self._pending_timestamps:
            timestamp = self._pending_timestamps[0]
            end_ms = round(timestamp.end_seconds * 1000)
            if end_ms > sent_ms:
                break

            self._pending_timestamps.pop(0)
            word_index = self._next_word_index
            self._next_word_index += 1
            if self._is_late_timestamp(end_ms, window_start_ms, sent_ms):
                self._timestamps_dropped = True
                continue

            start_ms = round(timestamp.start_seconds * 1000)
            if self._timestamps_dropped:
                markers.extend(self._fill_elapsed_until(start_ms))
            self._timestamps_dropped = False
            markers.append(
                PlaybackPosition(
                    kind="word",
                    word_index=word_index,
                    start_ms=start_ms,
                    offset_ms=end_ms,
                    timing_source="tts_word_timestamp",
                )
            )
            self._last_progress_ms = end_ms
        return markers

    def _is_late_timestamp(
        self, end_ms: int, window_start_ms: int, sent_ms: int
    ) -> bool:
        """Check whether this timestamp can no longer mark playback.

        A timestamp behind the last marker would move progress backwards. A
        timestamp that ends at or before the start of a send that advanced
        the position describes audio from an earlier window. A drain that
        adds no audio still marks words ending within audio already sent.
        """
        if end_ms <= self._last_progress_ms:
            return True
        return window_start_ms < sent_ms and end_ms <= window_start_ms

    def _elapsed_markers(self, sent_ms: int) -> List[PlaybackPosition]:
        """Fill each second of sent audio that no pending word starts inside.

        Offsets continue from the last marker. A pending word that starts before
        the next one-second mark covers that gap, so it stays unmarked. Elapsed
        markers resume once sent audio is a full second past the last marker,
        including when provider timestamps stop after earlier words.
        """
        next_marker_ms = self._last_progress_ms + _ELAPSED_MARKER_INTERVAL_MS
        if sent_ms < next_marker_ms:
            return []

        limit_ms = sent_ms
        if self._pending_timestamps:
            next_start_ms = round(self._pending_timestamps[0].start_seconds * 1000)
            if next_start_ms < next_marker_ms:
                return []
            limit_ms = min(limit_ms, next_start_ms)
        return self._fill_elapsed_until(limit_ms)

    def _fill_elapsed_until(self, limit_ms: int) -> List[PlaybackPosition]:
        markers: List[PlaybackPosition] = []
        while limit_ms - self._last_progress_ms >= _ELAPSED_MARKER_INTERVAL_MS:
            self._last_progress_ms += _ELAPSED_MARKER_INTERVAL_MS
            markers.append(
                PlaybackPosition(kind="audio_elapsed", offset_ms=self._last_progress_ms)
            )
        return markers

    @staticmethod
    def _is_valid(timestamp: TTSWordTimestamp) -> bool:
        return (
            math.isfinite(timestamp.start_seconds)
            and math.isfinite(timestamp.end_seconds)
            and timestamp.end_seconds >= timestamp.start_seconds
        )
